                return;
            }
            enqueue(()->{
            if(closed.get()||backend!=source)return;
            try { requestContext.accept(lastRuntime);
                var state=deferQueriesWhileBusy&&(busy()||event instanceof PortEvent.WorkspaceChanged) ? activitySnapshot()
