package com.mhtextractor.i18n;

import java.util.LinkedHashMap;
import java.util.Map;

/** One synchronous log call's original key/arguments. No rendered text crosses the IPC boundary. */
public record LogMessage(String key, Map<String, String> namedParams, String rendered) {
    private static final ThreadLocal<LogMessage> CURRENT = new ThreadLocal<>();

    static String remember(String key, Object[] args, String rendered) {
        var nested = CURRENT.get();
        var params = new LinkedHashMap<String, String>();
        for (int i = 0; i < args.length; i++) {
            String name = Integer.toString(i);
            if (nested != null && args[i] == nested.rendered) {
                params.put(name, "");
                params.put("$key." + name, nested.key);
                nested.namedParams.forEach((k,v) -> params.put("$arg." + name + "." + k, v));
            } else params.put(name, String.valueOf(args[i]));
        }
        CURRENT.set(new LogMessage(key, Map.copyOf(params), rendered));
        return rendered;
    }

    static String rememberNamed(String key, Map<String, String> params, String rendered) {
        CURRENT.set(new LogMessage(key, Map.copyOf(params), rendered));
        return rendered;
    }

    /** Identity prevents an unrelated equal string from reusing a stale key. Consume on all levels. */
    public static LogMessage take(String message) {
        var current = CURRENT.get();
        CURRENT.remove();
        return current != null && current.rendered == message ? current : null;
    }
}
package com.mhtextractor.app;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Locates the companion executable without depending on the view or a native-image API.
 *
 * <p><b>P4-21 打包布局</b>：发行目录把**后端独立**放在根目录下的 {@code Backend/} 子文件夹
 * （前端 exe + JavaFX/VC++ DLL 仍在根目录，dynamic 配方要求它们与前端 exe 同级）。
 * 解析顺序：{@code Backend/<exe>} → 根目录旧扁平布局（兼容旧发行包/开发期 jar），
 * 仍可用 {@code -Dmht.backend.executable=<path>} 覆盖。</p>
 */
public final class BackendExecutable {
    /** 随包后端可执行文件名。 */
    static final String BACKEND_EXE = "MhtExtractorBackend.exe";
    /** 持有后端的发行子目录（前端 exe 与 DLL 仍在根目录）。 */
    static final String BACKEND_DIR = "Backend";

    private BackendExecutable() { }

    public static Path resolve() {
        String override = System.getProperty("mht.backend.executable");
        if (override != null && !override.isBlank()) return Path.of(override).toAbsolutePath().normalize();
        return resolveIn(dataRoot());
    }

    /**
     * 在一个发行目录内解析：优先 {@code Backend/<exe>}（P4-21 当前布局），
     * 否则回退根目录旧布局（旧发行包 / jar 同目录 / 工作目录）。
     * 包级可见：让布局规则可以**脱离 native 镜像**做单元测试。
     */
    static Path resolveIn(Path folder) {
        Path nested = folder.resolve(BACKEND_DIR).resolve(BACKEND_EXE);
        return Files.isRegularFile(nested) ? nested : folder.resolve(BACKEND_EXE);
    }

    static Path dataRoot() {
        Path folder = Path.of("").toAbsolutePath();
        if (System.getProperty("org.graalvm.nativeimage.imagecode") != null) {
            return ProcessHandle.current().info().command().map(Path::of)
                    .map(Path::getParent).orElse(folder);
        }
        try {
            Path source = Path.of(BackendExecutable.class.getProtectionDomain().getCodeSource().getLocation().toURI());
            Path parent = source.toAbsolutePath().normalize().getParent();
            if (parent != null) return parent;
        } catch (Exception ignored) { /* Unavailable code source: use the launch working directory. */ }
        return folder;
    }

    static Path tempRoot() {
        return dataRoot().resolve(BACKEND_DIR).resolve("temp");
    }

    public static ProcessBuilder command(String locale) throws IOException {
        Files.createDirectories(dataRoot().resolve("logs"));
        Path executable = resolve();
        if (!Files.isRegularFile(executable)) throw new IOException("Backend executable missing: " + executable);
        Path temp = tempRoot();
        Files.createDirectories(temp);
        return new ProcessBuilder(executable.toString(), "-Djava.io.tmpdir=" + temp,
                "-Dmht.logs.root=" + dataRoot().resolve("logs"),
                "--serve", "--locale", locale).directory(dataRoot().toFile());
    }
}
|---|---|---|
| **dynamic（默认，≈70 MB）** | 在 EXE 外面，运行期 `System.load` | ✅ **必须随包**（glass / prism_common / prism_d3d / prism_sw / decora_sse / javafx_font / javafx_iio 共 7 个） |
| **static（≈98 MB）** | 已静态链接进 EXE | ❌ **绝不能放** |

- **static 下放了的后果**：EXE 同目录一旦存在 `glass.dll`，就会加载第二份 glass；静态链接那份的
  全局量从未初始化 → `com.sun.glass.ui.win.WinApplication._init` 解引用空指针。
- **对照实验（照这个格式做）**：同一份 static EXE，
  - 同目录放那 7 个 JavaFX DLL → `HasExited=True`，stderr 出现
    `[ [ SegfaultHandler caught a segfault ] ] ExceptionCode: -1073741819, reading address 0x0`；
  - 只放 native-image 自动落地的 9 个 JDK DLL + 5 个 VC 运行库 DLL → 正常出窗口。
- **修法**：`build-native.cmd` 第 4 步按配方决定抽哪些 DLL（并且**先清空** `target\jfx-dlls`，
  防止上一次另一种配方留下的 DLL 混进来），第 6 步把它们复制进 dist。

#### 10.3.5 元数据缺口：FXML 在第 24 行就崩

- **现象**：native EXE 能启动到 `FXMLLoader.load()`，然后
  `javafx.fxml.LoadException: /com/mhtextractor/gui/view/MainView.fxml:24`
  → `NoSuchMethodException: javafx.scene.control.ToggleGroup.<init>()`。
- **根因**：`MainView.fxml` 用 `<fx:define><ToggleGroup fx:id="modeToggleGroup"/></fx:define>`
  实例化控件，需要 `ToggleGroup` 的**反射构造器**条目，而当时的 `reachability-metadata.json` 里没有。
  同一轮 agent 采集还补出了 `com.sun.scenario.effect.impl.prism.ps.PPSBlend_SRC_INPeer` 与资源
  `.../hlsl/Blend_SRC_IN.obj`（混合效果用得到）。
- **修法**：跑 tracing agent（§10.6）并按**并集**合并。本次共补 **16 个反射类型 + 1 个资源**，
  `git diff --numstat` 为 **+128 / −0**（纯增量）。
- **教训**：**"能编译能链接"不等于"能跑"**。元数据缺口只在运行期炸，且往往炸在 FXML / Jackson / 资源这三处。

### 10.4 交付目录长什么样（两种配方，照抄即可）

**默认 = dynamic（≈70 MB / 22 个文件）** —— Oracle GraalVM，JavaFX 原生库随包：

```
MhtExtractor.exe        70,033,408 B   ← GUI 子系统（已 editbin）
glass.dll  prism_common.dll  prism_d3d.dll  prism_sw.dll  decora_sse.dll
javafx_font.dll  javafx_iio.dll                        ← 7 个 JavaFX DLL（**必须随包**）
awt.dll  fontmanager.dll  freetype.dll  java.dll  javaaccessbridge.dll
javajpeg.dll  jawt.dll  jvm.dll  lcms.dll              ← native-image 自动落地的 9 个 JDK DLL
msvcp140.dll  msvcp140_1.dll  msvcp140_2.dll  vcruntime140.dll  vcruntime140_1.dll
                                                       ← 5 个 VC++ 运行库
```

**可选 = static（≈98 MB / 15 个文件）** —— NIK Full，JavaFX 静态链接进 EXE：
同样这些文件，但 **去掉那 7 个 JavaFX DLL**（放了会段错误，§10.3.4）。

🚨 **dynamic 的 dist 还多两个文件：`启动.cmd` 与 `Launch.cmd`**（各约 2 KB）。**非 ASCII（中文）路径下
必须双击 `启动.cmd`**，直接双击 exe 会启动失败 —— 原因、对照实验与另外两个补救方案见 §10.8。
static 配方对路径无要求，直接双击 exe 即可。

两者都：
- **没有** `logs/`（应用首次运行才创建；打包时不要带）
- 整个目录**拷走即用**：无需 JDK/JRE，也无需预装 VC 运行库。
- **产物逐字节等价**：两种配方在 native 下都跑出 **42/0** 的产物黄金基线（§10.5.2），
  且与 JVM 产物树同名同内容。**选配方只影响体积，不影响产物。**

package com.mhtextractor.backend;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.UnsynchronizedAppenderBase;
import com.mhtextractor.i18n.LogMessage;
import com.mhtextractor.uiport.PortEvent;
import java.util.Map;
import java.util.function.Consumer;
import org.slf4j.LoggerFactory;

/** Session-owned synchronous appender. No appender lock is held while the callback pump applies backpressure. */
final class BackendLogForwarder extends UnsynchronizedAppenderBase<ILoggingEvent> implements AutoCloseable {
    private final Consumer<PortEvent.BackendLog> sink;
    private final ch.qos.logback.classic.Logger root;

    BackendLogForwarder(Consumer<PortEvent.BackendLog> sink) {
        this.sink = sink;
        var context = (LoggerContext) LoggerFactory.getILoggerFactory();
        setContext(context);
        setName("IPC_WARN_ERROR");
        root = context.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);
        start();
        root.addAppender(this);
    }

    @Override protected void append(ILoggingEvent event) {
        var message = LogMessage.take(event.getMessage());
        if (event.getLevel() != Level.WARN && event.getLevel() != Level.ERROR) return;
        String key = message == null ? "log.backend.unstructured" : message.key();
        Map<String, String> params = message == null ? Map.of("0", event.getLoggerName(),
                "1", event.getThrowableProxy() == null ? "" : event.getThrowableProxy().getClassName())
                : message.namedParams();
        sink.accept(new PortEvent.BackendLog(event.getLevel().toString(), key, params, event.getTimeStamp(), 0));
    }

    @Override public void close() { root.detachAppender(this); stop(); }
}
